id,name,address,lat,lng,description,category,author,created_at,status) select id,name,address,lat,lng,description,category,author,'2026-11-11T11:12:00.000Z'::timestamptz,'approved' from batch_facilities where not exists(select 1 from conflicts) returning id), inserted_courses as (insert into public.courses (id,name,lat,lng,path,tags,diff,distance,description,author,created_at,status) select id,name,lat,lng,path,tags,diff,distance,description,author,'2026-11-11T11:12:00.000Z'::timestamptz,'approved' from batch_courses where not exists(select 1 from conflicts) returning id) select 'facilities' as kind,count(*) as added from inserted_places union all select 'courses',count(*) from inserted_courses union all select 'conflicts',count(*) from conflicts;
